import pandas as pd
import numpy as np


def _is_null(v):
    return v is None or (isinstance(v, float) and pd.isna(v)) or (pd.isna(v) if not isinstance(v, (list, tuple)) else False)


def _dedupe_last(df: pd.DataFrame) -> pd.DataFrame:
    # Keep the last occurrence for each (region, sku) key, preserving
    # original row order as the deterministic tie-break ("latest wins").
    if df.empty:
        return df.copy()
    df = df.reset_index(drop=True)
    df['_ord'] = df.index
    df = df.sort_values('_ord')
    df = df.drop_duplicates(subset=['region', 'sku'], keep='last')
    df = df.drop(columns=['_ord'])
    return df.reset_index(drop=True)


def _num_equal(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return True
    if a_null or b_null:
        return False
    return a == b


def _label_equal(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return True
    if a_null or b_null:
        return False
    return a.rstrip(' ') == b.rstrip(' ')


def run(inputs: dict) -> dict:
    snap_prev = inputs["snap_prev"].copy()
    snap_curr = inputs["snap_curr"].copy()

    # Ensure expected columns exist and types are reasonable
    for df in (snap_prev, snap_curr):
        for col in ("region", "sku", "price", "stock", "label"):
            if col not in df.columns:
                df[col] = pd.NA

    # Deduplicate per key, deterministic "latest wins" on original order
    snap_prev = _dedupe_last(snap_prev)
    snap_curr = _dedupe_last(snap_curr)

    merged = pd.merge(
        snap_prev,
        snap_curr,
        on=["region", "sku"],
        how="outer",
        suffixes=("_prev", "_curr"),
        indicator=True,
    )

    rows = []

    for _, row in merged.iterrows():
        region = row["region"]
        sku = row["sku"]
        indicator = row["_merge"]

        if indicator == "left_only":
            rows.append({
                "region": region,
                "sku": sku,
                "change_type": "D",
                "changed_cols": None,
            })
            continue

        if indicator == "right_only":
            rows.append({
                "region": region,
                "sku": sku,
                "change_type": "I",
                "changed_cols": None,
            })
            continue

        # both present -> compare
        price_prev = row["price_prev"]
        price_curr = row["price_curr"]
        stock_prev = row["stock_prev"]
        stock_curr = row["stock_curr"]
        label_prev = row["label_prev"]
        label_curr = row["label_curr"]

        diffs = []
        if not _num_equal(price_prev, price_curr):
            diffs.append("price")
        if not _num_equal(stock_prev, stock_curr):
            diffs.append("stock")
        if not _label_equal(label_prev, label_curr):
            diffs.append("label")

        if diffs:
            rows.append({
                "region": region,
                "sku": sku,
                "change_type": "U",
                "changed_cols": ",".join(diffs),
            })
        # else: no row, identical

    change_log = pd.DataFrame(rows, columns=["region", "sku", "change_type", "changed_cols"])

    return {"change_log": change_log}
